const result = [];
for (const [index, item] of $input.all().entries()) {
  const event = item.json;
  if (event.field !== 'messages' || event.metadata?.phone_number_id !== 'META_PHONE_NUMBER_ID') continue;
  for (const m of event.messages ?? []) {
    const body = m.type === 'text' ? m.text?.body : ['image', 'video', 'document'].includes(m.type) ? m[m.type]?.caption : null;
    if (m.from !== 'DEMO_REMITENTE_META' || !m.id?.trim() || typeof body !== 'string' || !body.trim()) continue;
    const contact = (event.contacts ?? []).find(c => c.wa_id === m.from);
    const provider_profile_name = typeof contact?.profile?.name === 'string' ? contact.profile.name.trim() || null : null;
    result.push({json:{message_id:m.id, from:m.from, phone_number_id:event.metadata.phone_number_id, text:body, provider_profile_name}, pairedItem:{item:index}});
  }
}
return result;

const output = [];
for (const [index, item] of $input.all().entries()) {
  const event = item.json;
  const phoneId = event.metadata?.phone_number_id;
  if (event.field !== 'messages' || phoneId !== 'META_PHONE_NUMBER_ID') continue;
  for (const update of event.statuses ?? []) {
    if (update.recipient_id !== 'DEMO_REMITENTE_META' && update.recipient_id !== 'DEMO_DESTINATARIO_META_SIN_MAS') continue;
    output.push({
      json: { message_id: update.id, phone_number_id: phoneId, status: update.status },
      pairedItem: { item: index }
    });
  }
}
return output;

const r=$('Comprobar resolución').item.json, claim=$('Comprobar toma del turno').item.json;
const seed=$('Procesar cada mensaje').item.json, m=$json.body?.[0];
if ($json.body?.length!==1 || m?.id!==r.message_id || m.conversation_id!==r.conversation_id ||
    m.bot_cycle_id!==r.cycle_id || m.sender_kind!=='customer' || m.body!==claim.body ||
    !Number.isSafeInteger(m.history_position) || m.history_position<=0) throw new Error('Entrante distinto del resuelto');
return {json:{...r,receipt_id:claim.receipt_id,history_position:m.history_position,mensaje:m.body,
  provider_profile_name:seed.receipt_id===claim.receipt_id ? seed.provider_profile_name : null}};

const actual=$('Mensaje registrado').itemMatching(0).json;
const rows = $input.all().flatMap(p => {
  if (!Array.isArray(p.json.body)) throw new Error('Página de historial inválida.');
  return p.json.body;
});
let anterior = 0;
const ids = new Set();
const historial = rows.map(r => {
  if (!Number.isSafeInteger(r.history_position) || r.history_position <= anterior || r.history_position >= actual.history_position ||
      !r.message_id || r.message_id === actual.message_id || ids.has(r.message_id) || !['bot','customer'].includes(r.sender_kind))
    throw new Error('Página fuera de orden, autor inválido o mensaje repetido.');
  anterior = r.history_position; ids.add(r.message_id);
  return (r.sender_kind === 'customer' ? 'Cliente: ' : 'Bot: ') + r.body;
});

return [{json:{mensaje:actual.mensaje,historial:historial.join('\n')},pairedItem:{item:0}}];

