const datos = $('Extraer datos de la consulta').item.json.output;
const estado = $json.body?.[0];
const actual=$('Mensaje registrado').item.json;
if ($json.body?.length!==1 || estado?.disposition!=='resolved' ||
    ['lead_id','conversation_id','cycle_id','message_id'].some(k=>!actual[k] || estado[k]!==actual[k])) throw new Error('Ciclo o turno ajeno al entrante');
if (datos === null || typeof datos !== "object" || Array.isArray(datos)) {
  throw new Error("No hay datos extraidos en $json.output: se esperaba un objeto del extractor.");
}

const decisionesValidas = ["confirmada", "descartada", "indecisa", "no_informada"];
const decision = datos.decision_entrega_usado;
if (!decisionesValidas.includes(decision)) {
  throw new Error("decision_entrega_usado invalida: se esperaba confirmada, descartada, indecisa o no_informada (valor recibido: " + JSON.stringify(decision) + ").");
}
const usadoEsperado = decision === "confirmada" ? true : (decision === "descartada" ? false : null);
if (datos.tiene_usado !== usadoEsperado) {
  throw new Error("Inconsistencia: decision_entrega_usado=" + decision + " requiere tiene_usado=" + JSON.stringify(usadoEsperado) + " (valor recibido: " + JSON.stringify(datos.tiene_usado) + ").");
}

const cupos = estado.reserved_slots;
if (typeof cupos !== "number" || !Number.isInteger(cupos) || cupos < 0 || cupos > 3) {
  throw new Error("reserved_slots invalido: debe ser un entero entre 0 y 3 (valor recibido: " + JSON.stringify(cupos) + ").");
}

const faltante = (v) => v === null || v === undefined || (typeof v === "string" && v.trim() === "");

const CIERRE = "Gracias por la información. Un asesor de Pelucars va a contactarte para continuar con tu búsqueda.";

let accion;
let motivo;
let respuesta = null;

if (estado.closed_at != null || cupos === 3) {
  accion = "no_responder";
  motivo = "La conversación no admite otra reserva.";
} else if (cupos === 2) {
  accion = "cerrar";
  motivo = "Se reservaron 2 cupos: corresponde cerrar y derivar a un asesor.";
  respuesta = CIERRE;
} else {
  const caracteristicas = Array.isArray(datos.caracteristicas) ? datos.caracteristicas : [];

  if (faltante(datos.vehiculo_buscado) && caracteristicas.length === 0) {
    // A. Busqueda
    accion = "preguntar";
    motivo = "Falta saber que vehiculo o caracteristicas busca.";
    respuesta = "¡Hola! ¿Qué vehículo o qué características estás buscando?";
  } else {
    // B. Presupuesto (maximo dos aclaraciones)
    const faltantesPresupuesto = [];
    if (faltante(datos.presupuesto_importe)) faltantesPresupuesto.push({ campo: "importe", texto: "¿cuál es el importe de tu presupuesto?" });
    if (faltante(datos.presupuesto_moneda)) faltantesPresupuesto.push({ campo: "moneda", texto: "¿en qué moneda?" });
    if (faltante(datos.presupuesto_alcance)) faltantesPresupuesto.push({ campo: "alcance", texto: "¿ese monto es el valor total del vehículo o el dinero que podés agregar?" });
    const aPreguntar = faltantesPresupuesto.slice(0, 2);

    // C. Entrega de usado
    let preguntaUsado = null;
    let motivoUsado = null;
    if (decision === "no_informada") {
      preguntaUsado = "¿Tenés decidido entregar un vehículo como parte de pago?";
      motivoUsado = "El cliente no informo ninguna decision sobre la entrega de un vehiculo como parte de pago.";
    } else if (decision === "confirmada" && faltante(datos.usado_detalle)) {
      preguntaUsado = "¿Podés indicarme marca, modelo y año del vehículo que entregarías?";
      motivoUsado = "Entrega un usado pero falta el detalle (marca, modelo y año).";
    }

    // D. Plazo y financiacion
    const faltantesPlazo = [];
    if (faltante(datos.plazo_compra)) faltantesPlazo.push({ campo: "plazo_compra", texto: "¿para cuándo pensás concretar la compra?" });
    if (datos.necesita_financiacion === null || datos.necesita_financiacion === undefined) faltantesPlazo.push({ campo: "necesita_financiacion", texto: "¿necesitás financiación?" });

    if (aPreguntar.length > 0) {
      accion = "preguntar";
      motivo = "Presupuesto incompleto. Falta: " + faltantesPresupuesto.map((f) => f.campo).join(", ") + ". Se preguntan como maximo dos.";
      respuesta = "Para orientarte mejor, " + aPreguntar.map((f) => f.texto).join(" Y ") ;
    } else if (preguntaUsado !== null) {
      accion = "preguntar";
      motivo = motivoUsado;
      respuesta = preguntaUsado;
    } else if (faltantesPlazo.length > 0) {
      accion = "preguntar";
      motivo = "Faltan datos de plazo o financiacion: " + faltantesPlazo.map((f) => f.campo).join(", ") + ".";
      respuesta = faltantesPlazo.map((f) => f.texto).join(" Y ");
    } else {
      accion = "cerrar";
      motivo = "Todos los grupos de informacion estan respondidos.";
      respuesta = CIERRE;
    }
  }
}

return {
  json: {
    ...datos,
    reserved_slots: cupos,
    cycle_id: estado.cycle_id,
    message_id: $('Mensaje registrado').item.json.message_id,
    reply_kind: accion === 'preguntar' ? 'question' : accion === 'cerrar' ? 'closing' : null,
    accion,
    motivo,
    respuesta_propuesta: respuesta,
  },
};

const {statusCode,body}=$json;
if (statusCode>=200 && statusCode<300) return {json:{kind:'reserved',body}};
if (statusCode===409 && body?.code==='PT409') return {json:{kind:'stale'}};
throw new Error('Reserva rechazada: '+statusCode+' '+(body?.code??''));

const rows=$json.body;
if (!Array.isArray(rows) || rows.length>1) throw new Error('Lectura de reserva inválida');
if (rows.length) {
  const original=$('Decidir con los cupos actuales').item.json;
  if (rows[0].body!==original.respuesta_propuesta || rows[0].reply_kind!==original.reply_kind)
    throw new Error('La reserva existente difiere de la petición; conciliar sin enviar');
}
return {json:{body:rows}};

const row=Array.isArray($json.body)?$json.body[0]:$json.body;
if (!row?.id || row.conversation_id!==$('Mensaje registrado').item.json.conversation_id || row.reply_to!==$('Mensaje registrado').item.json.message_id || row.sender_kind!=='bot' || !row.body?.trim() || !['question','closing'].includes(row.reply_kind) || !Number.isInteger(row.bot_slot) || row.bot_slot<1 || row.bot_slot>3 || (row.bot_slot===3 && row.reply_kind!=='closing')) throw new Error('Reserva no verificable');
return {json:row};

const r=$json.body?.[0];
if ($json.body?.length!==1 || r?.message_id!==$('Respuesta persistida').item.json.id || typeof r.claimed!=='boolean' || (r.claimed && r.send_state!=='sending')) throw new Error('Toma no verificable');
return {json:{claimed:r.claimed}};

const reply = $('Respuesta persistida').item.json;
const messages = $json.messages;
const id = Array.isArray(messages) && messages.length === 1 ? messages[0]?.id : null;
const error = $json.error;
const response = error?.errorResponse ?? error?.response;
const graphError = response?.body?.error ?? response?.data?.error;
const status = Number(error?.httpCode ?? response?.statusCode ?? response?.status);
const accepted = !error && $json.messaging_product === 'whatsapp'
  && typeof id === 'string' && /^wamid\.\S+$/.test(id);
const rejected = [400, 401, 403, 404].includes(status)
  && Number.isInteger(graphError?.code) && graphError.is_transient !== true;
const result = {
  p_conversation_id: reply.conversation_id,
  p_message_id: reply.id,
  p_state: accepted ? 'sent' : rejected ? 'failed' : 'unknown',
};
if (accepted) result.p_provider_message_id = id;
return {json:result};

const message = $('Mensaje registrado').item.json;
const extraction = $json.output;
if (!extraction || typeof extraction !== 'object' || Array.isArray(extraction)) throw new Error('Falta la extracción del entrante');
const attributes = {};
for (const key of ['marca', 'modelo', 'anio_minimo', 'transmision']) {
  if (Object.hasOwn(extraction, key)) attributes[key] = extraction[key];
}
return {json: {
  p_conversation_id: message.conversation_id,
  p_message_id: message.message_id,
  p_extraction: extraction,
  p_attributes: attributes,
  p_provider_profile_name: message.provider_profile_name ?? null,
}};

const request = $('Preparar datos comerciales').item.json;
const rows = $json.body;
const row = rows?.[0];
if ($json.statusCode !== 200 || !Array.isArray(rows) || rows.length !== 1 || !['applied', 'unchanged'].includes(row?.outcome) || row.source_message_id !== request.p_message_id || row.lead_id !== $('Mensaje registrado').item.json.lead_id) {
  throw new Error('save_bot_lead_details: ' + (row?.outcome ?? 'respuesta inesperada') + '. Detener el turno y revisar el corte.');
}
return {json: request.p_extraction};

const d = $json;
const err = (m) => { throw new Error("Calcular score: " + m); };

const s = d.senales_score;
if (s === null || typeof s !== "object" || Array.isArray(s)) {
  err("senales_score ausente o invalido: se esperaba un objeto.");
}

const evidencias = (nombre) => {
  const v = s[nombre];
  if (!Array.isArray(v)) err(nombre + " invalido: se esperaba un array de textos.");
  v.forEach((x) => {
    if (typeof x !== "string") err(nombre + " invalido: todos los elementos deben ser texto.");
  });
  return v;
};
const tieneEvidencia = (arr) => arr.some((x) => x.trim() !== "");

const PLAZO = { hasta_7_dias: 30, de_8_a_30_dias: 20, de_31_a_90_dias: 10, mas_de_90_dias: 0, sin_definir: 0, ambiguo: 0, no_informado: 0 };
const INTENCION = { reserva_compra: 40, visita_prueba: 30, propuesta_concreta: 20, consulta_general: 0, no_informada: 0 };

const plazoCat = s.plazo_categoria;
if (typeof plazoCat !== "string" || !Object.prototype.hasOwnProperty.call(PLAZO, plazoCat)) {
  err("plazo_categoria desconocida: " + JSON.stringify(plazoCat) + ".");
}
const intCat = s.intencion_categoria;
if (typeof intCat !== "string" || !Object.prototype.hasOwnProperty.call(INTENCION, intCat)) {
  err("intencion_categoria desconocida: " + JSON.stringify(intCat) + ".");
}

const evPlazo = evidencias("plazo_evidencias");
const evIntencion = evidencias("intencion_evidencias");
const evBusqueda = evidencias("busqueda_evidencias");
const evPresupuesto = evidencias("presupuesto_evidencias");

if (d.caracteristicas !== undefined && d.caracteristicas !== null && !Array.isArray(d.caracteristicas)) {
  err("caracteristicas invalido: se esperaba un array.");
}
const caracteristicas = Array.isArray(d.caracteristicas) ? d.caracteristicas : [];

const exigirEvidencia = (grupo, puntos, evid) => {
  if (puntos > 0 && !tieneEvidencia(evid)) {
    err("el grupo " + grupo + " aporta " + puntos + " puntos pero no tiene evidencias con texto.");
  }
};

// 1. Plazo
const ptsPlazo = PLAZO[plazoCat];
exigirEvidencia("plazo", ptsPlazo, evPlazo);

// 2. Intencion
const ptsIntencion = INTENCION[intCat];
exigirEvidencia("intencion", ptsIntencion, evIntencion);

// 3. Busqueda
const hayVehiculo = typeof d.vehiculo_buscado === "string" && d.vehiculo_buscado.trim() !== "";
const hayCaracteristicas = caracteristicas.some((c) => typeof c === "string" && c.trim() !== "");
const busquedaDefinida = hayVehiculo || hayCaracteristicas;
const ptsBusqueda = busquedaDefinida ? 15 : 0;
exigirEvidencia("busqueda", ptsBusqueda, evBusqueda);

// 4. Presupuesto
const importeValido = typeof d.presupuesto_importe === "number" && Number.isFinite(d.presupuesto_importe) && d.presupuesto_importe >= 0;
const monedaValida = d.presupuesto_moneda === "ARS" || d.presupuesto_moneda === "USD";
const alcanceValido = d.presupuesto_alcance === "valor_total" || d.presupuesto_alcance === "dinero_a_agregar";
const presupuestoCompleto = importeValido && monedaValida && alcanceValido;
const ptsPresupuesto = presupuestoCompleto ? 15 : 0;
exigirEvidencia("presupuesto", ptsPresupuesto, evPresupuesto);

const total = ptsPlazo + ptsIntencion + ptsBusqueda + ptsPresupuesto;
const banda = total >= 60 ? "alta" : (total >= 30 ? "media" : "baja");

const motivos = [];
if (plazoCat === "ambiguo") motivos.push("El plazo de compra es ambiguo: su normalizacion temporal todavia no esta definida.");
if (plazoCat === "no_informado") motivos.push("El cliente no informo el plazo de compra.");
if (intCat === "no_informada") motivos.push("No hay una intencion clasificable.");
if (!busquedaDefinida) motivos.push("Falta una busqueda definida (vehiculo o caracteristicas).");
if (!presupuestoCompleto) motivos.push("El presupuesto esta incompleto (importe, moneda o alcance).");
if (d.presupuesto_alcance === "dinero_a_agregar" && d.decision_entrega_usado === "indecisa") {
  motivos.push("El importe esta condicionado: es dinero a agregar y el cliente no decidio si entrega su usado.");
}

return {
  json: {
    ...d,
    evaluacion_score: {
      version_reglas: "pelucars_score_v1_prototipo",
      total,
      banda,
      desglose: {
        plazo: { puntos: ptsPlazo, motivo: "plazo_categoria = " + plazoCat, evidencias: evPlazo },
        intencion: { puntos: ptsIntencion, motivo: "intencion_categoria = " + intCat, evidencias: evIntencion },
        busqueda: { puntos: ptsBusqueda, motivo: busquedaDefinida ? "Hay vehiculo o caracteristicas definidas." : "No hay vehiculo ni caracteristicas definidas.", evidencias: evBusqueda },
        presupuesto: { puntos: ptsPresupuesto, motivo: presupuestoCompleto ? "Importe, moneda y alcance completos." : "Presupuesto incompleto.", evidencias: evPresupuesto },
      },
      informacion_limitada: motivos.length > 0,
      motivos_limitacion: motivos,
    },
  },
};

const rows = $json.body;
const row = rows?.[0];
if ($json.statusCode !== 200 || !Array.isArray(rows) || rows.length !== 1 || !row?.evaluation_id || !['applied', 'unchanged'].includes(row.outcome)) {
  throw new Error('save_bot_score: ' + (row?.outcome ?? 'respuesta inesperada'));
}
return {json: row};

const [r] = $json.body ?? [];
if ($json.body?.length !== 1 || typeof r?.created !== 'boolean' ||
    !['pending','processing','resolved','paused','review','historical','noncommercial'].includes(r.disposition) ||
    (!r.receipt_id && r.disposition !== 'historical')) throw new Error('Ingreso D07 inesperado');
const event = $('Mensajes entrantes').item.json;
return {json:{...r,phone_e164:'+'+event.from,provider_profile_name:event.provider_profile_name}};

const r=$json.body?.[0];
if ($json.body?.length!==1 || typeof r?.claimed!=='boolean' || !r.reason ||
    r.receipt_id!==$('Comprobar cola').item.json.receipt_id || r.claimed!==(r.reason==='claimed') ||
    (r.claimed && (typeof r.body!=='string' || !r.body.trim()))) throw new Error('Toma D07 inesperada');
return {json:r};

const rows=$json.body;
if (!Array.isArray(rows) || rows.some(r=>!r.id || r.customers?.phone_e164!==$('Procesar cada mensaje').item.json.phone_e164)) throw new Error('Búsquedas ajenas al contacto');
const body=$('Comprobar toma del turno').item.json.body;
const candidates=rows.slice(0,10).map((r,i)=>({opcion:i+1,id:r.id,resumen:(r.summary ?? '').slice(0,700)}));
return {json:{body,candidates,bounded:rows.length<=10 && body.length<=8000}};

const ctx=$('Contexto de clasificación').item.json;
const result=ctx.bounded ? $json.output : {decision:'uncertain',opcion:0,cita:''};
const allowed=['same_search','new_search','additional_purchase','noncommercial','uncertain'];
if (!result || !allowed.includes(result.decision) || !Number.isInteger(result.opcion) || typeof result.cita!=='string') throw new Error('Clasificación inválida');
let decision=result.decision;
let target=null;
const candidates=ctx.candidates;
const quote=result.cita.trim();
if (['same_search','new_search'].includes(decision)) {
  const selected=candidates.find(c=>c.opcion===result.opcion);
  if (candidates.length===1 && [0,1].includes(result.opcion)) target=candidates[0].id;
  else if (candidates.length>1 && selected && quote.length>=3 && ctx.body.includes(quote) &&
           selected.resumen.toLowerCase().includes(quote.toLowerCase()) &&
           candidates.filter(c=>c.resumen.toLowerCase().includes(quote.toLowerCase())).length===1) target=selected.id;
  else if (candidates.length || decision==='same_search' || result.opcion!==0) decision='uncertain';
} else if (decision==='additional_purchase' && (!quote || !ctx.body.includes(quote) || result.opcion!==0)) decision='uncertain';
return {json:{p_receipt_id:$('Comprobar toma del turno').item.json.receipt_id,p_decision:decision,p_lead_id:target}};

const r=$json.body?.[0];
if ($json.body?.length!==1 || !['resolved','review','noncommercial'].includes(r?.outcome) ||
    (r.outcome==='resolved' && ![r.message_id,r.lead_id,r.conversation_id,r.cycle_id].every(Boolean))) throw new Error('Resolución D07 inválida');
return {json:r};

const rows=$json.body, e=rows?.[0], old=$('Decidir con los cupos actuales').item.json;
if (rows?.length!==1 || !e || e.cycle_id!==old.cycle_id ||
    (!e.closed_at && !(e.reserved_slots>old.reserved_slots))) throw new Error('PT409 sin avance del ciclo; conciliar el recibo y su reserva');
return {json:$json};
